// BAD: N+1 — one query for users, then one per user for posts.
var users []User
db.Find(&users)
for i := range users {
	db.Model(&users[i]).
		Association("Posts").
		Find(&users[i].Posts) // +1 query EACH time
}

// GOOD: Preload eager-loads all posts in ONE batched query.
var preloaded []User
db.Preload("Posts").Find(&preloaded)
// SQL: SELECT * FROM users;
//      SELECT * FROM posts WHERE user_id IN (1,2,3,...);

// For a belongs-to, Joins folds it into a single query:
var posts []Post
db.Joins("User").Find(&posts)
